def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for h in history:
        if h[1] == 'D':
            opp_def += 1

    if n >= 10 and opp_def * 2 > n:
        return 'D'

    if n >= 95 and history[-1][1] == 'D':
        return 'D'

    if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'

    return 'C'
